type ReservePipelineCandidateVersionRow struct {
	ID                 pgtype.UUID        `json:"id"`
	DocumentID         pgtype.UUID        `json:"document_id"`
	AssetID            pgtype.UUID        `json:"asset_id"`
	VersionNumber      int32              `json:"version_number"`
	Status             string             `json:"status"`
	Sha1               string             `json:"sha1"`
	Sha256             string             `json:"sha256"`
	ContentType        string             `json:"content_type"`
	SizeBytes          int64              `json:"size_bytes"`
	StorageObjectID    pgtype.UUID        `json:"storage_object_id"`
	ChunkingConfigHash string             `json:"chunking_config_hash"`
	PipelineConfigHash string             `json:"pipeline_config_hash"`
	ReadyAt            pgtype.Timestamptz `json:"ready_at"`
	ActivatedAt        pgtype.Timestamptz `json:"activated_at"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	DeletedAt          pgtype.Timestamptz `json:"deleted_at"`
	ErrorCode          string             `json:"error_code"`
	ErrorMessage       string             `json:"error_message"`
	IdentityID         pgtype.UUID        `json:"identity_id"`
	SearchDocumentID   string             `json:"search_document_id"`
	PipelineGeneration int64              `json:"pipeline_generation"`
	Replayed           bool               `json:"replayed"`
	ReplayIsActive     pgtype.Bool        `json:"replay_is_active"`
}

// Reserves the version that owns these exact bytes AND writes the asset's storage-object
// ledger row AND binds the asset to the resulting document+version -- in one statement.
//
// One statement rather than four because the four could interleave: a repeat upload of
// identical bytes would create a fresh raw object and then attach it to the OLD immutable
// version, and a repeat ingest would redo conversion, embedding and projection that the
// recorded version already owns.
//
// The object INSERT names a version that does not exist yet, and the version names that
// object, because both foreign keys are DEFERRABLE INITIALLY DEFERRED (0093:378-394) and
// the remaining immediate one is checked at end of statement, by which time both rows are
// present.
//
// Data-modifying CTEs cannot observe each other's effects on the underlying tables, so
// every hand-off here travels through a RETURNING projection -- `inserted` reads
// `asset_object.id`, never aura.storage_objects a second time.
func (q *Queries) ReservePipelineCandidateVersion(ctx context.Context, arg ReservePipelineCandidateVersionParams) (ReservePipelineCandidateVersionRow, error) {
	row := q.db.QueryRow(ctx, reservePipelineCandidateVersion,
		arg.DocumentID,
		arg.IdentityID,
		arg.AssetID,
		arg.Sha256,
		arg.ID,
		arg.Bucket,
		arg.ObjectKey,
		arg.Sha1,
		arg.Etag,
		arg.SizeBytes,
		arg.ContentType,
		arg.RetentionClass,
		arg.Status,
		arg.ChunkingConfigHash,
		arg.PipelineConfigHash,
	)
	var i ReservePipelineCandidateVersionRow
	err := row.Scan(
		&i.ID,
		&i.DocumentID,
		&i.AssetID,
		&i.VersionNumber,
		&i.Status,
		&i.Sha1,
		&i.Sha256,
		&i.ContentType,
		&i.SizeBytes,
		&i.StorageObjectID,
		&i.ChunkingConfigHash,
		&i.PipelineConfigHash,
		&i.ReadyAt,
		&i.ActivatedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.ErrorCode,
		&i.ErrorMessage,
		&i.IdentityID,
		&i.SearchDocumentID,
		&i.PipelineGeneration,
		&i.Replayed,
		&i.ReplayIsActive,
	)
	return i, err
}

